import{_ as u,a0 as g,w as e,s as a,I as i,x as t,a1 as r,A as n,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"如何衡量一个开源社区的健康度 | LCTT x X-CMD","titleTemplate":false,"description":"如何衡量一个开源社区的健康度 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何衡量一个开源社区的健康度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何衡量一个开源社区的健康度 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190811 How to measure the health of an open source community","title":"如何衡量一个开源社区的健康度","tag":"201908","desc":""},"relativePath":"201908/20190811 How to measure the health of an open source community.md","filePath":"[post].md"}'),p={name:"201908/20190811 How to measure the health of an open source community.md"};function m(d,l,f,S,T,C){const o=g("Link");return e(),a("div",null,[l[35]||(l[35]=i("h1",{id:"如何衡量一个开源社区的健康度",tabindex:"-1"},[t("如何衡量一个开源社区的健康度 "),i("a",{class:"header-anchor",href:"#如何衡量一个开源社区的健康度","aria-label":"Permalink to “如何衡量一个开源社区的健康度”"},"​")],-1)),l[36]||(l[36]=i("blockquote",null,[i("p",null,"这比较复杂。")],-1)),l[37]||(l[37]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/19/184719nz3xuazppzu3vwcg.jpg",alt:""})],-1)),l[38]||(l[38]=i("p",null,"作为一个经常管理软件开发团队的人，多年来我一直关注度量指标。一次次，我发现自己领导团队使用一个又一个的项目平台（例如 Jira、GitLab 和 Rally）生成了大量可测量的数据。从那时起，我已经及时投入了大量时间从记录平台中提取了有用的指标，并采用了一种我们可以理解的格式，然后使用这些指标对开发的许多方面做出更好的选择。",-1)),i("p",null,[l[3]||(l[3]=t("今年早些时候，我有幸在 ",-1)),r(o,{href:"https://www.linuxfoundation.org/"},{default:n(()=>[...l[0]||(l[0]=[t("Linux 基金会",-1)])]),_:1}),l[4]||(l[4]=t("遇到了一个名为",-1)),i("ruby",null,[r(o,{href:"https://chaoss.community/"},{default:n(()=>[...l[1]||(l[1]=[t("开源软件社区健康分析",-1)])]),_:1}),l[2]||(l[2]=i("rt",null,"Community Health Analytics for Open Source Software",-1))]),l[5]||(l[5]=t("（CHAOSS）的项目。该项目侧重于从各种来源收集和丰富指标，以便开源社区的利益相关者可以衡量他们项目的健康状况。",-1))]),l[39]||(l[39]=s('<h3 id="chaoss-介绍" tabindex="-1">CHAOSS 介绍 <a class="header-anchor" href="#chaoss-介绍" aria-label="Permalink to “CHAOSS 介绍”">​</a></h3><p>随着我对该项目的基本指标和目标越来越熟悉，一个问题在我的脑海中不断翻滚。什么是“健康”的开源项目，由谁来定义？</p><p>特定角色的人认为健康的东西可能另一个角色的人就不会这样认为。似乎可以用 CHAOSS 收集的细粒度数据进行市场细分实验，重点关注对特定角色可能最有意义的背景问题，以及 CHAOSS 收集哪些指标可能有助于回答这些问题。</p><p>CHAOSS 项目创建并维护了一套开源应用程序和度量标准定义，使得这个实验具有可能性，这包括：</p><ul><li>许多基于服务器的应用程序，用于收集、聚合和丰富度量标准（例如 Augur 和 GrimoireLab）。</li><li>ElasticSearch、Kibana 和 Logstash（ELK）的开源版本。</li><li>身份服务、数据分析服务和各种集成库。</li></ul><p>在我过去的一个程序中，有六个团队从事于不同复杂程度的项目，我们找到了一个简洁的工具，它允许我们从简单（或复杂）的 JQL 语句中创建我们想要的任何类型的指标，然后针对这些指标开发计算。在我们注意到之前，我们仅从 Jira 中就提取了 400 多个指标，而且还有更多指标来自手动的来源。</p><p>在项目结束时，我们认定这 400 个指标中，大多数指标在<em>以我们的角色</em>做出决策时并不重要。最终，只有三个对我们非常重要：“缺陷去除效率”、“已完成的条目与承诺的条目”，以及“每个开发人员的工作进度”。这三个指标最重要，因为它们是我们对自己、客户和团队成员所做出的承诺，因此是最有意义的。</p><p>带着这些通过经验得到的教训和对什么是健康的开源项目的问题，我跳进了 CHAOSS 社区，开始建立一套角色，以提供一种建设性的方法，从基于角色的角度回答这个问题。</p><p>CHAOSS 是一个开源项目，我们尝试使用民主共识来运作。因此，我决定使用<ruby>组成分子<rt>constituent</rt></ruby>这个词而不是利益相关者，因为它更符合我们作为开源贡献者的责任，以创建更具共生性的价值链。</p><p>虽然创建此组成模型的过程采用了特定的“目标-问题-度量”方法，但有许多方法可以进行细分。CHAOSS 贡献者已经开发了很好的模型，可以按照矢量进行细分，例如项目属性（例如，个人、公司或联盟）和“失败容忍度”。在为 CHAOSS 开发度量定义时，每个模型都会提供建设性的影响。</p><p>基于这一切，我开始构建一个谁可能关心 CHAOSS 指标的模型，以及每个组成分子在 CHAOSS 的四个重点领域中最关心的问题：</p>',11)),i("ul",null,[i("li",null,[r(o,{href:"https://github.com/chaoss/wg-diversity-inclusion"},{default:n(()=>[...l[6]||(l[6]=[t("多样性和包容性",-1)])]),_:1})]),i("li",null,[r(o,{href:"https://github.com/chaoss/wg-evolution"},{default:n(()=>[...l[7]||(l[7]=[t("演化",-1)])]),_:1})]),i("li",null,[r(o,{href:"https://github.com/chaoss/wg-risk"},{default:n(()=>[...l[8]||(l[8]=[t("风险",-1)])]),_:1})]),i("li",null,[r(o,{href:"https://github.com/chaoss/wg-value"},{default:n(()=>[...l[9]||(l[9]=[t("价值",-1)])]),_:1})])]),l[40]||(l[40]=s('<p>在我们深入研究之前，重要的是要注意 CHAOSS 项目明确地将背景判断留给了实施指标的团队。什么是“有意义的”和“什么是健康的？”的答案预计会因团队和项目而异。CHAOSS 软件的现成仪表板尽可能地关注客观指标。在本文中，我们关注项目创始人、项目维护者和贡献者。</p><h3 id="项目组成分子" tabindex="-1">项目组成分子 <a class="header-anchor" href="#项目组成分子" aria-label="Permalink to “项目组成分子”">​</a></h3><p>虽然这绝不是这些组成分子可能认为重要的问题的详尽清单，但这些选择感觉是一个好的起点。以下每个“目标-问题-度量”标准部分与 CHAOSS 项目正在收集和汇总的指标直接相关。</p><p>现在，进入分析的第 1 部分！</p><h4 id="项目创始人" tabindex="-1">项目创始人 <a class="header-anchor" href="#项目创始人" aria-label="Permalink to “项目创始人”">​</a></h4><p>作为<strong>项目创始人</strong>，我<strong>最</strong>关心：</p>',6)),i("ul",null,[l[16]||(l[16]=s("<li>我的项目<strong>对其他人有用吗？</strong>通过以下测量： <ul><li>随着时间推移有多少复刻？ <ul><li><strong>指标：</strong>存储库复刻数。</li></ul></li><li>随着时间的推移有多少贡献者？ <ul><li><strong>指标：</strong>贡献者数量。</li></ul></li><li>贡献净质量。 <ul><li><strong>指标：</strong>随着时间的推移提交的错误。</li><li><strong>指标：</strong>随着时间的回归。</li></ul></li><li>项目的财务状况。 <ul><li><strong>指标：</strong>随着时间的推移的捐赠/收入。</li><li><strong>指标：</strong>随着时间的推移的费用。</li></ul></li></ul></li><li>我的项目对其它人的<strong>可见</strong>程度？ <ul><li>有谁知道我的项目？别人认为它很整洁吗？ <ul><li><strong>指标：</strong>社交媒体上的提及、分享、喜欢和订阅的数量。</li></ul></li><li>有影响力的人是否了解我的项目？ <ul><li><strong>指标：</strong>贡献者的社会影响力。</li></ul></li><li>人们在公共场所对项目有何评价？是正面还是负面？ <ul><li><strong>指标：</strong>跨社交媒体渠道的情感（关键字或 NLP）分析。</li></ul></li></ul></li><li>我的项目<strong>可行性</strong>程度？ <ul><li>我们有足够的维护者吗？该数字是随着时间的推移而上升还是下降？ <ul><li><strong>指标：</strong>维护者数量。</li></ul></li><li>改变速度如何随时间变化？ <ul><li><strong>指标：</strong>代码随时间的变化百分比。</li><li><strong>指标：</strong>拉取请求、代码审查和合并之间的时间。</li></ul></li></ul></li>",3)),i("li",null,[l[11]||(l[11]=t("我的项目的",-1)),r(o,{href:"https://github.com/chaoss/wg-diversity-inclusion"},{default:n(()=>[...l[10]||(l[10]=[t("多样化 ＆ 包容性",-1)])]),_:1}),l[12]||(l[12]=s("如何？ <ul><li>我们是否拥有有效的公开行为准则（CoC）？ <ul><li><strong>度量标准：</strong> 检查存储库中的 CoC 文件。</li></ul></li><li>与我的项目相关的活动是否积极包容？ <ul><li><strong>指标：</strong>关于活动的票务政策和活动包容性行为的手动报告。</li></ul></li><li>我们的项目在可访问性上做的好不好？ <ul><li><strong>指标：</strong>验证发布的文字会议纪要。</li><li><strong>指标：</strong>验证会议期间使用的隐藏式字幕。</li><li><strong>指标：</strong>验证在演示文稿和项目前端设计中色盲可访问的素材。</li></ul></li></ul>",2))]),i("li",null,[l[14]||(l[14]=t("我的项目代表了多少",-1)),r(o,{href:"https://github.com/chaoss/wg-value"},{default:n(()=>[...l[13]||(l[13]=[t("价值",-1)])]),_:1}),l[15]||(l[15]=s("？ <ul><li>我如何帮助组织了解使用我们的项目将节省多少时间和金钱（劳动力投资） <ul><li><strong>指标：</strong>仓库的议题、提交、拉取请求的数量和估计人工费率。</li></ul></li><li>我如何理解项目创建的下游价值的数量，以及维护我的项目对更广泛的社区的重要性（或不重要）？ <ul><li><strong>指标：</strong>依赖我的项目的其他项目数。</li></ul></li><li>为我的项目做出贡献的人有多少机会使用他们学到的东西来找到合适的工作岗位，以及在哪些组织（即生活工资）？ <ul><li><strong>指标：</strong>使用或贡献此库的组织数量。</li><li><strong>指标：</strong>使用此类项目的开发人员的平均工资。</li><li><strong>指标：</strong>与该项目匹配的关键字的职位发布计数。</li></ul></li></ul>",2))])]),l[41]||(l[41]=s('<h3 id="项目维护者" tabindex="-1">项目维护者 <a class="header-anchor" href="#项目维护者" aria-label="Permalink to “项目维护者”">​</a></h3><p>作为<strong>项目维护者</strong>，我<strong>最</strong>关心：</p><ul><li>我是<strong>高效的</strong>维护者吗？ <ul><li><strong>指标：</strong>拉取请求在代码审查之前等待的时间。</li><li><strong>指标：</strong>代码审查和后续拉取请求之间的时间。</li><li><strong>指标：</strong>我的代码审核中有多少被批准？</li><li><strong>指标：</strong>我的代码评论中有多少被拒绝或返工？</li><li><strong>指标：</strong>代码审查的评论的情感分析。</li></ul></li><li>我如何让<strong>更多人</strong>帮助我维护这件事？ <ul><li><strong>指标：</strong>项目贡献者的社交覆盖面数量。</li></ul></li><li>我们的<strong>代码质量</strong>随着时间的推移变得越来越好吗？ <ul><li><strong>指标：</strong>计算随着时间的推移引入的回归数量。</li><li><strong>指标：</strong>计算随着时间推移引入的错误数量。</li><li><strong>指标：</strong>错误归档、拉取请求、代码审查、合并和发布之间的时间。</li></ul></li></ul><h3 id="项目开发者和贡献者" tabindex="-1">项目开发者和贡献者 <a class="header-anchor" href="#项目开发者和贡献者" aria-label="Permalink to “项目开发者和贡献者”">​</a></h3><p>作为<strong>项目开发者或贡献者</strong>，我<strong>最</strong>关心：</p><ul><li>我可以从为这个项目做出贡献中获得哪些有价值的东西，以及实现这个价值需要多长时间？ <ul><li><strong>指标：</strong>下游价值。</li><li><strong>指标：</strong>提交、代码审查和合并之间的时间。</li></ul></li><li>通过使用我在贡献中学到的东西来增加工作机是否有良好的前景？ <ul><li><strong>指标：</strong>生活工资。</li></ul></li><li>这个项目有多受欢迎？ <ul><li><strong>指标：</strong>社交媒体帖子、分享和收藏的数量。</li></ul></li><li>社区有影响力的人知道我的项目吗？ <ul><li><strong>指标：</strong>创始人、维护者和贡献者的社交范围。</li></ul></li></ul><p>通过创建这个列表，我们开始让 CHAOSS 更加丰满了，并且在今年夏天项目中首次发布该指标时，我迫不及待地想看看广泛的开源社区可能有什么其他伟大的想法，以及我们还可以从这些贡献中学到什么（并衡量！）。</p><h3 id="其它角色" tabindex="-1">其它角色 <a class="header-anchor" href="#其它角色" aria-label="Permalink to “其它角色”">​</a></h3><p>接下来，你需要了解有关其他角色（例如基金会、企业开源计划办公室、业务风险和法律团队、人力资源等）以及最终用户的目标问题度量集的更多信息。他们关心开源的不同事物。</p>',9)),i("p",null,[l[18]||(l[18]=t("如果你是开源贡献者或组成分子，我们邀请你",-1)),r(o,{href:"https://github.com/chaoss/"},{default:n(()=>[...l[17]||(l[17]=[t("来看看这个项目",-1)])]),_:1}),l[19]||(l[19]=t("并参与社区活动！",-1))]),l[42]||(l[42]=i("hr",null,null,-1)),i("p",null,[l[21]||(l[21]=t("via: ",-1)),r(o,{href:"https://opensource.com/article/19/8/measure-project"},{default:n(()=>[...l[20]||(l[20]=[t("https://opensource.com/article/19/8/measure-project",-1)])]),_:1})]),i("p",null,[l[26]||(l[26]=t("作者：",-1)),r(o,{href:"https://opensource.com/users/the3rdlaw"},{default:n(()=>[...l[22]||(l[22]=[t("Jon Lawrence",-1)])]),_:1}),l[27]||(l[27]=t(" 选题：",-1)),r(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...l[23]||(l[23]=[t("lujun9972",-1)])]),_:1}),l[28]||(l[28]=t(" 译者：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...l[24]||(l[24]=[t("wxy",-1)])]),_:1}),l[29]||(l[29]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...l[25]||(l[25]=[t("wxy",-1)])]),_:1})]),i("p",null,[l[32]||(l[32]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[30]||(l[30]=[t("LCTT",-1)])]),_:1}),l[33]||(l[33]=t(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...l[31]||(l[31]=[t("Linux中国",-1)])]),_:1}),l[34]||(l[34]=t(" 荣誉推出",-1))])])}const x=u(p,[["render",m]]);export{h as __pageData,x as default};
